-- Carga legada Decretacoes (MySQL dbsdc -> PostgreSQL sdc).
-- Gerado por _build_pg_load.py. NAO editar a mao.
-- Estrategia: STAGING + filtro anti-orfao + TRUNCATE/reload, transacional (ACID).

\set ON_ERROR_STOP on
BEGIN;
SET client_encoding TO 'UTF8';

-- (1) Tabelas de staging sem constraints (FK desligada por construcao).
CREATE TEMP TABLE stg_dec_decreto_categorias (LIKE dec_decreto_categorias) ON COMMIT DROP;
CREATE TEMP TABLE stg_dec_desastre_grupos (LIKE dec_desastre_grupos) ON COMMIT DROP;
CREATE TEMP TABLE stg_dec_desastre_categorias (LIKE dec_desastre_categorias) ON COMMIT DROP;
CREATE TEMP TABLE stg_dec_desastre_items (LIKE dec_desastre_items) ON COMMIT DROP;
CREATE TEMP TABLE stg_dec_desastre_item_campos (LIKE dec_desastre_item_campos) ON COMMIT DROP;
CREATE TEMP TABLE stg_dec_entrada_processos (LIKE dec_entrada_processos) ON COMMIT DROP;
CREATE TEMP TABLE stg_dec_entrada_decretos (LIKE dec_entrada_decretos) ON COMMIT DROP;
CREATE TEMP TABLE stg_dec_decreto_municipios (LIKE dec_decreto_municipios) ON COMMIT DROP;
CREATE TEMP TABLE stg_dec_entrada_categoria_desastres (LIKE dec_entrada_categoria_desastres) ON COMMIT DROP;
CREATE TEMP TABLE stg_dec_entrada_desastres (LIKE dec_entrada_desastres) ON COMMIT DROP;

-- (2) Carga bruta dos dumps no staging (INSERTs em lote de 500).
-- staging dec_decreto_categorias: 11 linha(s)

-- staging dec_desastre_grupos: 4 linha(s)

-- staging dec_desastre_categorias: 8 linha(s)

-- staging dec_desastre_items: 43 linha(s)

-- staging dec_desastre_item_campos: 92 linha(s)

-- staging dec_entrada_processos: 485 linha(s)

-- staging dec_entrada_decretos: 19 linha(s)

-- staging dec_decreto_municipios: 630 linha(s)

-- staging dec_entrada_categoria_desastres: 2488 linha(s)

-- staging dec_entrada_desastres: 18257 linha(s)

-- (3) Limpa as tabelas reais.
TRUNCATE TABLE
    dec_entrada_desastres,
    dec_entrada_categoria_desastres,
    dec_decreto_municipios,
    dec_entrada_decretos,
    dec_entrada_processos,
    dec_desastre_item_campos,
    dec_desastre_items,
    dec_desastre_categorias,
    dec_desastre_grupos,
    dec_decreto_categorias
    RESTART IDENTITY CASCADE;

-- (4) Carga filtrada staging -> real, em ordem de FK.
    SELECT id, nome, descricao, created_at, updated_at FROM stg_dec_decreto_categorias;
    SELECT id, titulo, numero, created_at, updated_at FROM stg_dec_desastre_grupos;
    SELECT id, titulo, informacao, descricao, created_at, updated_at, desastre_grupo_id FROM stg_dec_desastre_categorias;
    SELECT id, categoria_id, titulo, observacao, created_at, updated_at FROM stg_dec_desastre_items
    WHERE categoria_id IN (SELECT id FROM dec_desastre_categorias);
    SELECT id, tipo, titulo, desastre_item_id, created_at, updated_at FROM stg_dec_desastre_item_campos
    WHERE desastre_item_id IN (SELECT id FROM dec_desastre_items);
    SELECT id, data_ocorrencia_desastre, data_entrada, processo, analista, n_protocolo_fide, decreto_municipal, tipo_desastre_id, tipo_desastre, data_decreto_municipal, data_publicacao_mg, prazo_vigencia, reconhecimento, reconhecimento_decreto_n_data, data_publicacao_diario, portaria_reconhecimento_fed, portaria_diario_oficial, reconhecimento_federal, observacoes, processo_inserido_sei, created_at, updated_at, deleted_at, created_by FROM stg_dec_entrada_processos;
-- (4b) Stubs de processos-pai ausentes no legado (preserva filhos orfaos).
    SELECT DISTINCT refs.pid, 'legado-stub',
           'Stub carga legada: processo-pai ausente no dump legado; mantido para preservar filhos orfaos.',
           TIMESTAMP '2026-06-03 00:00:00'
    FROM (
        SELECT entrada_processos_id AS pid FROM stg_dec_entrada_decretos
        UNION SELECT entrada_processos_id FROM stg_dec_decreto_municipios
        UNION SELECT entrada_processo_id  FROM stg_dec_entrada_categoria_desastres
        UNION SELECT entrada_processo_id  FROM stg_dec_entrada_desastres
    ) refs
    WHERE refs.pid NOT IN (SELECT id FROM dec_entrada_processos);
    SELECT id, entrada_processos_id, decreto_categoria_id, observacao, created_at, updated_at, deleted_at FROM stg_dec_entrada_decretos
    WHERE entrada_processos_id IN (SELECT id FROM dec_entrada_processos)
      AND decreto_categoria_id IN (SELECT id FROM dec_decreto_categorias);
    SELECT id, entrada_processos_id, n_protocolo_fide, municipio_id, created_at, updated_at FROM stg_dec_decreto_municipios
    WHERE entrada_processos_id IN (SELECT id FROM dec_entrada_processos);
    SELECT id, municipio_id, categoria_id, entrada_processo_id, descricao, created_at, updated_at, deleted_at FROM stg_dec_entrada_categoria_desastres
    WHERE categoria_id IN (SELECT id FROM dec_desastre_categorias)
      AND entrada_processo_id IN (SELECT id FROM dec_entrada_processos);
    SELECT id, municipio_id, item_id, item_campo_id, entrada_processo_id, entrada_categoria_desastre_id, campo_titulo, valor, created_at, updated_at, deleted_at FROM stg_dec_entrada_desastres
    WHERE entrada_processo_id IN (SELECT id FROM dec_entrada_processos)
      AND entrada_categoria_desastre_id IN (SELECT id FROM dec_entrada_categoria_desastres)
      AND item_id IN (SELECT id FROM dec_desastre_items)
      AND item_campo_id IN (SELECT id FROM dec_desastre_item_campos);

-- (5) Reposiciona sequences (IDs explicitos foram inseridos).
SELECT setval(pg_get_serial_sequence('dec_decreto_categorias', 'id'), GREATEST((SELECT COALESCE(MAX(id), 1) FROM dec_decreto_categorias), 1));
SELECT setval(pg_get_serial_sequence('dec_desastre_grupos', 'id'), GREATEST((SELECT COALESCE(MAX(id), 1) FROM dec_desastre_grupos), 1));
SELECT setval(pg_get_serial_sequence('dec_desastre_categorias', 'id'), GREATEST((SELECT COALESCE(MAX(id), 1) FROM dec_desastre_categorias), 1));
SELECT setval(pg_get_serial_sequence('dec_desastre_items', 'id'), GREATEST((SELECT COALESCE(MAX(id), 1) FROM dec_desastre_items), 1));
SELECT setval(pg_get_serial_sequence('dec_desastre_item_campos', 'id'), GREATEST((SELECT COALESCE(MAX(id), 1) FROM dec_desastre_item_campos), 1));
SELECT setval(pg_get_serial_sequence('dec_entrada_processos', 'id'), GREATEST((SELECT COALESCE(MAX(id), 1) FROM dec_entrada_processos), 1));
SELECT setval(pg_get_serial_sequence('dec_entrada_decretos', 'id'), GREATEST((SELECT COALESCE(MAX(id), 1) FROM dec_entrada_decretos), 1));
SELECT setval(pg_get_serial_sequence('dec_decreto_municipios', 'id'), GREATEST((SELECT COALESCE(MAX(id), 1) FROM dec_decreto_municipios), 1));
SELECT setval(pg_get_serial_sequence('dec_entrada_categoria_desastres', 'id'), GREATEST((SELECT COALESCE(MAX(id), 1) FROM dec_entrada_categoria_desastres), 1));
SELECT setval(pg_get_serial_sequence('dec_entrada_desastres', 'id'), GREATEST((SELECT COALESCE(MAX(id), 1) FROM dec_entrada_desastres), 1));

-- (6) Relatorio: linhas no staging vs carregadas (diferenca = orfas descartadas).
SELECT 'dec_decreto_categorias' AS tabela, (SELECT count(*) FROM stg_dec_decreto_categorias) AS staged, (SELECT count(*) FROM dec_decreto_categorias) AS carregado
UNION ALL SELECT 'dec_desastre_grupos' AS tabela, (SELECT count(*) FROM stg_dec_desastre_grupos) AS staged, (SELECT count(*) FROM dec_desastre_grupos) AS carregado
UNION ALL SELECT 'dec_desastre_categorias' AS tabela, (SELECT count(*) FROM stg_dec_desastre_categorias) AS staged, (SELECT count(*) FROM dec_desastre_categorias) AS carregado
UNION ALL SELECT 'dec_desastre_items' AS tabela, (SELECT count(*) FROM stg_dec_desastre_items) AS staged, (SELECT count(*) FROM dec_desastre_items) AS carregado
UNION ALL SELECT 'dec_desastre_item_campos' AS tabela, (SELECT count(*) FROM stg_dec_desastre_item_campos) AS staged, (SELECT count(*) FROM dec_desastre_item_campos) AS carregado
UNION ALL SELECT 'dec_entrada_processos' AS tabela, (SELECT count(*) FROM stg_dec_entrada_processos) AS staged, (SELECT count(*) FROM dec_entrada_processos) AS carregado
UNION ALL SELECT 'dec_entrada_decretos' AS tabela, (SELECT count(*) FROM stg_dec_entrada_decretos) AS staged, (SELECT count(*) FROM dec_entrada_decretos) AS carregado
UNION ALL SELECT 'dec_decreto_municipios' AS tabela, (SELECT count(*) FROM stg_dec_decreto_municipios) AS staged, (SELECT count(*) FROM dec_decreto_municipios) AS carregado
UNION ALL SELECT 'dec_entrada_categoria_desastres' AS tabela, (SELECT count(*) FROM stg_dec_entrada_categoria_desastres) AS staged, (SELECT count(*) FROM dec_entrada_categoria_desastres) AS carregado
UNION ALL SELECT 'dec_entrada_desastres' AS tabela, (SELECT count(*) FROM stg_dec_entrada_desastres) AS staged, (SELECT count(*) FROM dec_entrada_desastres) AS carregado
ORDER BY tabela;

COMMIT;
